			lea pa_sum2_g, a1
			move.l (a0)+, (a1)+
			move.l (a0)+, (a1)+
			move.l (a0)+, (a1)+
			clr.w var_sum2_sum2
			clr.w var_sum2_r
			clr.w var_sum2_c
			move.l sp, p_sum2_rs
			lea p_sum2, sp
			rts
p_sum2_r:		; end of sum2
			movea.l p_sum2_rs, sp
			rts
p_cols_c:		; call cols
			movea.l (sp)+, a0		; g() descriptor
			lea pa_cols_g, a1
			move.l (a0)+, (a1)+
			move.l (a0)+, (a1)+
			move.l (a0)+, (a1)+
			clr.w var_cols_cols
			move.l sp, p_cols_rs
			lea p_cols, sp
			rts
p_cols_r:		; end of cols
			movea.l p_cols_rs, sp
			rts
p_clear2_c:		; call clear2
