;## ntc_div
; d0.w / d1.w signed, truncating: d0.w = quotient, d1.w = remainder (the
; dividend's sign). Divide by zero: quotient 0, remainder = dividend.
; -32768 / -1: quotient -32768, remainder 0 (as the Z80 library). jmp (a6)
ntc_div:
			tst.w d1
			beq ntc_div_z
			ext.l d0
			move.l d0, d2
			divs.w d1, d0
			bvs ntc_div_ov
			move.l d0, d1
			swap d1
			jmp (a6)
ntc_div_z:
			move.w d0, d1
			moveq #0, d0
			jmp (a6)
ntc_div_ov:
			move.w #$8000, d0
			moveq #0, d1
			jmp (a6)

			even
;## kw_divvv ntc_div
;kw_divvv, <var1>, <var2>, <destvar>  - var1 \ var2
kw_divvv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			move.w (a1), d1
			lea kw_div_q, a6
			bra ntc_div
kw_div_q:
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

